/**
 * Strict-JSON wire helpers.
 *
 * `JSON.stringify` already escapes C0 control characters inside the
 * string literals it produces, so bodies it generates are spec-legal.
 * The gap this module closes is JSON text that reaches the wire WITHOUT
 * passing through `JSON.stringify` on the final document — most notably
 * the verbatim tool-call `arguments` string (`partial_json`,
 * `function_call_arguments.delta`, `FunctionCallOutputItem.arguments`,
 * and persisted `inputJson`/`outputJson` rows): that payload is JSON
 * generated by the MODEL, which routinely leaves raw `\n`, `\t`, or
 * other control characters inside string literals. A strict client
 * parser (Python's default `json.loads`, most proxies) rejects them.
 *
 * {@link sanitizeJsonString} is a port of the Rust-side
 * `sanitize_json_string` in `crates/mlx-core/src/tools/chatml.rs`: a
 * small state machine that escapes raw control characters found INSIDE
 * JSON string literals (`\n`, `\r`, `\t`, `\b`, `\f`, `\uXXXX` for the
 * rest, plus DEL to mirror `char::is_ascii_control`) while leaving
 * already-escaped sequences, structural characters, and whitespace
 * between tokens untouched — byte-identical for compliant input.
 *
 * {@link stringifyStrictJson} wraps `JSON.stringify` so every wire
 * emission site is belt-and-braces strict even if a future path
 * bypasses the normal serializer.
 */

/**
 * Escape raw control characters found inside JSON string literals.
 *
 * Idempotent: compliant JSON passes through unchanged, so callers may
 * apply it to strings that are already strictly valid without risk of
 * double-escaping. A trailing lone backslash inside a string is copied
 * verbatim (the caller's downstream parser reports the malformed input;
 * the sanitizer only ever FIXES control characters, never corrupts).
 */
/** Escape sequence (with leading backslash) for a C0/DEL control char. */
function escapeControl(code: number): string {
  switch (code) {
    case 0x0a:
      return '\\n';
    case 0x0d:
      return '\\r';
    case 0x09:
      return '\\t';
    case 0x08:
      return '\\b';
    case 0x0c:
      return '\\f';
    default:
      return `\\u${code.toString(16).padStart(4, '0')}`;
  }
}

export function sanitizeJsonString(input: string): string {
  let out = '';
  let inString = false;
  let i = 0;
  const len = input.length;
  while (i < len) {
    const c = input.charAt(i);
    i += 1;
    if (inString) {
      if (c === '\\') {
        // Escaped character — copy the backslash and the next char as-is,
        // except when the "escape" is a raw control char (malformed
        // input): then emit `\\` + the escaped control so the output
        // stays strictly parseable.
        const next = i < len ? input.charAt(i) : '';
        const nextCode = next.charCodeAt(0);
        if (nextCode <= 0x1f || nextCode === 0x7f) {
          out += '\\\\';
          out += escapeControl(nextCode);
          i += 1;
        } else {
          out += c;
          if (i < len) {
            out += input.charAt(i);
            i += 1;
          }
        }
      } else if (c === '"') {
        inString = false;
        out += c;
      } else {
        const code = c.charCodeAt(0);
        if (code <= 0x1f || code === 0x7f) {
          out += escapeControl(code);
        } else {
          out += c;
        }
      }
    } else {
      if (c === '"') {
        inString = true;
      }
      out += c;
    }
  }
  return out;
}

/**
 * `JSON.stringify` followed by a belt-and-braces pass of
 * {@link sanitizeJsonString}: any raw control character that somehow
 * reached the serialized document inside a string literal is escaped
 * before it can hit the wire. Byte-identical to `JSON.stringify` for
 * every compliant payload, so it is a drop-in replacement at all
 * emission sites.
 */
export function stringifyStrictJson(
  value: unknown,
  replacer?: ((this: unknown, key: string, value: unknown) => unknown) | (string | number)[] | null,
  space?: string | number | null,
): string {
  // `JSON.stringify` is typed `string` but returns `undefined` at runtime
  // for non-serializable roots (undefined/function/symbol) — `undefined`
  // is not valid at the top level of a JSON document, so fall back to a
  // strict `null` instead of ever letting the literal reach the wire.
  // `JSON.stringify`'s overloads take either a function OR an array
  // replacer; `null` behaves identically to `undefined` at runtime, so
  // normalise both up front and pick the matching overload.
  const out: string | undefined = Array.isArray(replacer)
    ? JSON.stringify(value, replacer, space ?? undefined)
    : JSON.stringify(value, replacer ?? undefined, space ?? undefined);
  return out === undefined ? 'null' : sanitizeJsonString(out);
}
